EXTENDED_SENTIMENT_CATALOG_SHA256 = (
    "97588427dc123e69a7f42523cbc776a45b1abba0496a89c4d36ef973d5a507aa"
)

SENTIMENT_TERMS: tuple[tuple[str, str, str], ...] = (
    *(
        (word, language, value)
        for spanish, english, value in SENTIMENT_LEXICON
        for word, language in ((spanish, "es"), (english, "en"))
    ),
    *EXTENDED_SENTIMENT_TERMS,
)
SENTIMENT_SEED_BATCH_SIZE = 500


def seed_sentiment_configuration(session: Session) -> None:
    rows = [
        {
            "clave": key,
            "valor": value,
            "tipo": parameter_type,
            "descripcion": description,
        }
        for key, (value, parameter_type, description) in SENTIMENT_SETTINGS.items()
    ]
    try:
        session.execute(
            insert(Configuration)
            .values(rows)
            .on_conflict_do_nothing(index_elements=["clave"])
        )
        session.commit()
    except Exception:
        session.rollback()
        raise


def seed_sentiment_terms(session: Session) -> None:
    rows = [
        {
            "palabra": word,
            "idioma": language,
            "valor": Decimal(value),
            "activo": True,
        }
        for word, language, value in SENTIMENT_TERMS
    ]
    try:
        for start in range(0, len(rows), SENTIMENT_SEED_BATCH_SIZE):
            session.execute(
                insert(Term)
                .values(rows[start : start + SENTIMENT_SEED_BATCH_SIZE])
                .on_conflict_do_nothing(constraint="uq_termino_palabra_idioma")
            )
        session.commit()
    except Exception:
        session.rollback()
        raise
